void test__test_operators__test_vector_ops(void) {
test__test_operators__Vector2 v1 = test__test_operators__Vector2_init(10, 20);
test__test_operators__Vector2 v2 = test__test_operators__Vector2_init(3, 5);
test__test_operators__Vector2 v_add = test__test_operators__Vector2_plus_2(&v1, v2);
testsupport__assert__assert_eq_i32(v_add.x, 13, KOBEL_STR("Vector2 + Vector2: x"));
testsupport__assert__assert_eq_i32(v_add.y, 25, KOBEL_STR("Vector2 + Vector2: y"));
test__test_operators__Vector2 v_scalar = test__test_operators__Vector2_plus_2_2(&v1, 100);
testsupport__assert__assert_eq_i32(v_scalar.x, 110, KOBEL_STR("Vector2 + i32: x"));
testsupport__assert__assert_eq_i32(v_scalar.y, 120, KOBEL_STR("Vector2 + i32: y"));
test__test_operators__Vector2 v_sub = test__test_operators__Vector2_minus(&v1, v2);
testsupport__assert__assert_eq_i32(v_sub.x, 7, KOBEL_STR("Vector2 - Vector2: x"));
testsupport__assert__assert_eq_i32(v_sub.y, 15, KOBEL_STR("Vector2 - Vector2: y"));
test__test_operators__Vector2 v_mul = test__test_operators__Vector2_mul(&v1, 3);
testsupport__assert__assert_eq_i32(v_mul.x, 30, KOBEL_STR("Vector2 * i32: x"));
testsupport__assert__assert_eq_i32(v_mul.y, 60, KOBEL_STR("Vector2 * i32: y"));
test__test_operators__Vector2 v_neg = test__test_operators__Vector2_negate(&v1);
testsupport__assert__assert_eq_i32(v_neg.x, -10, KOBEL_STR("-Vector2: x"));
testsupport__assert__assert_eq_i32(v_neg.y, -20, KOBEL_STR("-Vector2: y"));
testsupport__assert__assert_true(test__test_operators__Vector2_equals(&v1, test__test_operators__Vector2_init(10, 20)), KOBEL_STR("Vector2 == Vector2 (equal)"));
testsupport__assert__assert_true(!test__test_operators__Vector2_equals(&v1, v2), KOBEL_STR("Vector2 != Vector2 (not equal)"));
test__test_operators__Vector2 v_mut = test__test_operators__Vector2_init(1, 2);
test__test_operators__Vector2_plus_assign(&v_mut, test__test_operators__Vector2_init(10, 20));
testsupport__assert__assert_eq_i32(v_mut.x, 11, KOBEL_STR("Vector2 += Vector2: x"));
testsupport__assert__assert_eq_i32(v_mut.y, 22, KOBEL_STR("Vector2 += Vector2: y"));
}

