testsupport__assert__assert_true(std__collections__HashSet_str_contains(&set, KOBEL_STR("ptr_key")), KOBEL_STR("'ptr_key' in &set"));
testsupport__assert__assert_true(std__collections__HashMap_str_i32_contains(&map, KOBEL_STR("ptr_k")), KOBEL_STR("'ptr_k' in &map"));
