testsupport__assert__assert_eq_i32(*std__collections__HashMap_str_i32_get(map_ptr, KOBEL_STR("ptr_k")), 123, KOBEL_STR("*(&map)['ptr_k'] == 123"));
std__collections__HashMap_str_i32_free(map);
